   "source": "2016年吉林省公务员录用考试《行测》题（乙级） · 第16题",
   "question": "王戎七岁，尝与诸小儿游，见道边李树多子折枝。诸儿竞走取之，唯戎不动。人问之，答曰：“树在道边而多子，此必苦李。”取之信然。\n王戎的隐含推理的假设是：",
   "options": [
    "A. 若路边的李子被摘光了，就不会多子折枝。",
    "B. 若路边的李子味道甜美，就不会多子折枝。",
    "C. 若路边的李子味道不甜美，就会多子折枝。",
    "D. 只有路边的李子没被摘光，才会多子折枝。"
   ],
   "answer": "B",
   "analysis": "第一步：找出论点和论据。\n论点：此必苦李。\n论据：树在道边而多子。\n论点讨论的是李子是苦的，而论据讨论的是树在道路边并且李子很多，论点和论据话题不一致，优先考虑搭桥，即树在道边而多子img/formula-91cb3505d485006d.webp此必苦李。\n第二步：逐一分析选项。\nA项：李子被摘光img/formula-91cb3505d485006d.webp不会多子折枝，李子是否摘光和题干讨论的话题不一致，无法加强，排除；\nB项：李子味道甜美img/formula-91cb3505d485006d.webp不会多子折枝，将其逆否，多子折枝img/formula-91cb3505d485006d.webp李子味道不甜美，在论点和论据之间搭桥，可以加强，当选；\nC项：李子味道不甜美img/formula-91cb3505d485006d.webp会多子折枝，无法加强，排除；\nD项：多子折枝img/formula-91cb3505d485006d.webp李子没被摘光，李子是否摘光和题干讨论的话题不一致，无法加强，排除。\n故正确答案为B。",
   "exam": "jilin",
   "year": 2016
