   "question": "稀缺效应，是指人们因物以稀为贵，而引起的购买行为变化的现象，即当某件事物变得稀缺或者难以得到时，人们会认为此物更有价值，也更想得到。\n根据上述定义，下列没有体现稀缺效应的是：",
   "options": [
    "A. 商店每天都挂着打折仅此一天的横幅吸引大量顾客",
    "B. 某品牌手机实行网上预约销售限量抢购，结果供不应求",
    "C. 月底经济拮据的小张靠着去超市购买临期食品度日",
    "D. 男性在临近酒吧打烊时会认为女性的吸引力指数上升了"
   ],
   "answer": "C",
