   "source": "2016年吉林省公务员录用考试《行测》题（甲级） · 第17题",
   "question": "概念混淆，是指由于自然语言的多义性和模糊性而产生的非形式谬误。构型歧义，是指由于句子语法结构的不正确而产生的歧义性谬误。\n根据上述定义，下列选项中属于构型歧义的是：",
