   "question": "近日，某国的科学家们正在尝试用粒子加速器治疗癌症。他们将包括脑胶质瘤细胞在内的几种肿瘤细胞培养物放置在模拟人类头部的有机玻璃器皿中。再把这个“人头”放在粒子加速器的作用范围内。科学家们首次在肿瘤细胞内聚集着足够量的硼-10，然后再用中子束照射肿瘤部位。使肿瘤细胞内部发生核反应，肿瘤细胞随之死亡。\n以下哪项如果为真，最能支持实验的成功？",
