   "question": "某出版商认为：加工成本在近5年上升了img/formula-f74801b8674b37ff.webp~img/formula-db6a2b01ee8920be.webp；原材料成本上升了img/formula-f74801b8674b37ff.webp~img/formula-fbcd04d8ef29962c.webp；销售及广告成本上升了img/formula-f74801b8674b37ff.webp以上。将所有这些加起来的话，总成本至少上升了img/formula-2f29ab37e5278826.webp。这仅是对大型出版社而言，如果是小出版社，总成本至少上升了img/formula-cff51b12d085da1c.webp。可见，书价的上涨主要是成本的上涨造成的，因此我反对提高作家的版权收入。\n对上述论证的评价，最恰当的是：",
