   "module": "判断推理",
   "source": "2018年421联考《行测》题（吉林乙级） · 第24题",
   "question": "某企业拟开设4门培训课程：《企业文化培训》《劳动法培训》《商务礼仪培训》《销售培训》。员工甲乙丙丁4人各选修了其中一门课程。已知：\n①他们4人选修的课程各不相同；\n②法律专业毕业的丙选修的是非法律类课程；\n③甲选修的不是《企业文化培训》就是《商务礼仪培训》。\n补充以下哪个条件，能确定丙选修的是《销售培训》？",
