   "question": "反向谬论，是指依据某观点若成立（或不成立）所产生的结果好坏，来判断一个观点是否正确的一种逻辑错误。\n根据上述定义，下列存在反向谬论的是：",
   "options": [
    "A. 因为你迟到，客户生气了，公司损失一个大合同，所以都是你的错",
    "B. 尽管担心加税会对选民生活产生不利影响，政治家仍表示支持加税",
    "C. 如果你不听我的话，我就会扣你的零用钱，所以你听我的话是对的",
    "D. 自从做眼保健操以来，我的视力急剧地下降，可见做眼保健操不好"
   ],
   "answer": "C",
   "analysis": "第一步：找出定义关键词。\n“依据某观点若成立（或不成立）所产生的结果好坏 ”、“判断一个观点是否正确”。\n第二步：逐一分析选项。\nA项：“因为你迟到，客户生气了”是已经发生的事情，不符合“某观点若成立（或不成立）”，不符合定义，排除； \nB项：加税会对选民生活产生不利影响，符合“某观点若成立（或不成立）所产生的结果”，但政治家仍支持加税，不是依据加税对生活产生不利影响而做出的判断，不符合定义，排除；\nC项：“如果你不听我的话”符合“依据某观点若成立（或不成立）”，“我就会扣你的零用钱”是一个不好的结果，所以得出“你听我的话是对的”的结论，符合“依据某观点产生的结果来判断一个观点是否正确”，符合定义，当选；\nD项：“做眼保健操视力下降”是已经发生的事情，不符合“某观点若成立（或不成立）”，不符合定义，排除。\n故正确答案为C。",
