   "question": "墙面色彩的确定，首先要考虑房间的朝向。南向和东向的房间，光照充足，墙面宜采用浅蓝、浅绿等冷色调；北向房间，墙面应以奶黄等暖色调为主。墙面的色彩对于家具起背景衬托作用，所以宜用浅色调。另外，宽敞的房间采用暖色装修，可以避免给人以空旷感；面积小的房间采用冷色装修，在视觉上让人感觉大一些。\n下列最符合上述室内色彩设计基本原则的是：",
