   "source": "2019年420联考《行测》题（吉林乙级） · 第7题",
   "question": "热岛效应是指城市由于人口集中，工业、交通、居民生活等产生大量的人为热量而使城市的气温高于郊区的现象。雨岛效应是指由于热岛效应，在城市上空产生一股上升气流，加上上空尘埃较多，使附近及下风向降水稍多的现象。温室效应是指由于人类活动排放大量温室气体而造成全球气候变暖的现象。\n根据上述定义，下列说法错误的是：",
   "options": [
    "A. 热岛效应是引起雨岛效应的原因之一",
    "B. 热岛效应是引起温室效应的唯一原因",
    "C. 热岛效应和温室效应影响的地域范围不同",
    "D. 三种效应都是人类活动对气候影响的结果"
   ],
   "answer": "B",
   "analysis": "第一步：找出定义关键词。\n热岛效应：“城市由于人口集中，工业、交通、居民生活等产生大量的人为热量而使城市的气温高于郊区”；\n雨岛效应：“由于热岛效应，在城市上空产生一股上升气流，加上上空尘埃较多，附近及下风向降水稍多”；\n温室效应：“由于人类活动排放大量温室气体而造成全球气候变暖”。\n第二步：逐一分析选项。\nA项：热岛效应是引起雨岛效应的原因之一，雨岛效应定义中明确说明是由于热岛效应产生，符合雨岛效应定义，说法正确，排除；\nB项：涉及到热岛效应和温室效应两个定义间关系，温室效应产生原因为“人类活动排放大量温室气体”，而热岛效应是“城市中产生大量人为热量”，人类活动包含城市和非城市人群的活动，所以热岛效应不是引起温室效应的唯一原因，表述绝对不准确，当选；\nC项：热岛效应影响的地域范围为“城市的气温高于郊区”，温室效应的影响范围为“全球气候变暖”，一个是城市，一个是全球，所以影响范围不同，说法正确，排除；\nD项：根据定义三种效应产生的原因分别“由于人口集中，产生大量的人为热量”，“由于热岛效应”，“由于人类活动”，热岛效应就是人类活动影响，所以三种效应都是人类活动对气候影响的结果，说法正确，排除。\n本题为选非题，故正确答案为B。",
   "exam": "jilin",
   "year": 2019
