   "module": "判断推理",
   "source": "2019年420联考《行测》题（吉林乙级） · 第23题",
   "question": "对夏天的虫子无法谈论冬天的冰，因为它根本活不到冬天，自然不知道冬天的冰是什么样的。同样的道理，大学生刚毕业，如果不锻炼两年，怎能做好销售工作呢？\n下列选项与题干所犯的论证错误最相似的是：",
