   "question": "先赋资本是指建立在血缘、遗传等先天条件下，不经过个人努力就可以拥有的资本。自致资本是指通过个人后天努力取得，为个人所支配的资本。\n根据上述定义，下列选项中的内容均属于自致资本的是：",
