   "source": "2021年吉林省公务员录用考试《行测》题 · 第8题",
   "question": "虚假相关指的是两个没有因果关系的事件之间，基于一些其他未见的因素（潜在变量）而推断出因果关系，引致两个事件是“有所联系”的假象，但这种联系并不能通过客观的试验来证实。\n根据上述定义，下列选项不属于虚假相关的是:",
