   "question": "不粘锅常见的不粘涂层为特氟龙涂层。全氟辛酸铵是特氟龙生产过程中使用的含量极微的一种加工助剂。数据表明，高剂量的全氟辛酸铵有可能导致胆固醇水平升高、甲状腺疾病及不育。特氟龙在常温及常态下具有非常稳定的理化性质，使用特氟龙不粘涂层的炊具在常温至img/formula-823da7bed56f7db8.webp的温度范围内都不会发生任何变化，但是当温度超过img/formula-823da7bed56f7db8.webp时，涂层逐渐向不稳定状态转变，当温度超过img/formula-c05dc400f545d33b.webp时会发生分解。正常烹调时，水的沸点是img/formula-54236b9343026c76.webp，温度较高的爆炒通常也只是img/formula-ecdb39124022aa1c.webp左右，即使采用油炸的方式，油温也不会超过img/formula-db3ee25e989df2f8.webp。然而，如果在炒菜时喜欢把锅烧干、烧红后再加油，锅内温度就容易超过img/formula-823da7bed56f7db8.webp。\n由此无法推出的是：",
