   "question": "动机-效率定律是心理学家提出的反映动机水平与工作效率关系的定律。心理学家认为动机水平的强度和工作效率之间的关系不是一种正比例关系，而是形成一种倒U形曲线，如下图所示。\nimg/1868892481c0564.webp\n根据上述定义，下列说法错误的是：",
