   "question": "地貌学是研究地球表面形态的特征、成因、内部结构分布及其演变规律的学科。构造地貌学是研究构造运动、地质构造与地貌形态之间关系的学科。气候地貌学是研究受气候控制的地表形态特征及其发生、发展规律的学科。动力地貌学是研究各种外动力在地貌形成中的作用及其形成的地貌形态特征的学科。外动力包括流水、冰川、波浪、风、溶解和热力冻融等。构造地貌学、气候地貌学和动力地貌学都属于地貌学的分支学科。\n根据上述定义，下列不属于地貌学上述三个分支学科研究范畴的是：",
