   "question": "距今约2.52亿年前的二叠纪末大灭绝，让超过八成的海洋物种和约九成的陆地物种消失。近期，研究人员运用红外光谱，定量测量了我国西藏南部二叠纪、三叠纪过渡期1000多粒陆地植物花粉粒的物质含量。结果显示，在二叠纪大灭绝期间，花粉外壁中香豆酸和阿魏酸的含量明显升高。研究人员据此认为，在二叠纪末大灭绝期间，大气紫外线辐射的强度明显增强。\n上述论证的成立须补充以下哪项作为前提？",
