   "question": "随着人口老龄化程度加剧，慢性病患者和失能、半失能老人数量与日俱增。近年来某市不少医院推出“互联网+护理”服务，老人们在家通过手机APP下单，医护人员就可以上门提供服务。省去了老人们频繁跑医院的烦恼。但是，自该项服务推出以来，“成交量”始终不温不火。不少医院表示，去年一年的接单量不足50单。可见，该市老人对“互联网+护理”服务的需求并不高。\n以下除哪项外，均能削弱上述结论？",
