   "question": "以昆虫为原料研发动物饲料正在成为一种潮流。一家生产动物饲料的公司正在开发将黑水虻幼虫磨碎，进而加工成鱼饲料的技术。黑水虻是产卵后4天就孵化、14天变为成虫的一种昆虫，其幼虫除富含蛋白质外，还富含生物生长不可缺少的钙和必需的氨基酸。这种昆虫可以在短时间内大量繁殖，成为谷物饲料的替代品。该公司认为，以黑水虻幼虫等昆虫生产动物饲料，有助于减少粮食浪费。\n以下哪项如果为真，最能支持上述结论？",
