   "source": "2023年吉林省公务员录用考试《行测》题 · 第29题",
   "question": "地球的生命起源一直是个谜。在地球岩浆期之前，地球上已经具备氨基酸生成的条件，但高温岩浆的普遍覆盖可能将它们全部消灭。因此，地球生命源于外太空的说法逐渐占据主导地位。近日，研究人员从来自“龙宫”小行星的砂土中发现了20多种氨基酸，其中包括不能在体内产生的异亮氨酸，也包括我们熟知的谷氨酸。研究人员认为，这为地球生命起源于外太空提供了强有力的佐证。\n以下哪项如果为真，最能质疑上述结论？",
   "options": [
    "A. 实验证明，氨基酸在岩浆的高温条件下无法存活",
    "B. 此前检测出氨基酸的陨石是从某深海打捞上来的",
    "C. 有相关研究表明，地球表面并未被岩浆完全覆盖",
    "D. 其它小行星和月球表面未发现氨基酸存在的痕迹"
   ],
   "answer": "C",
   "analysis": "第一步：找出论点和论据。\n论点：地球生命起源于外太空。\n论据：在地球岩浆期之前，地球上已经具备氨基酸生成的条件，但高温岩浆的普遍覆盖可能将它们全部消灭。近日，研究人员从来自“龙宫”小行星的砂土中发现了20多种氨基酸，其中包括不能在体内产生的异亮氨酸，也包括我们熟知的谷氨酸。\n本题论点和论据均在讨论“地球的生命起源”，论点论据话题一致，削弱优先考虑削弱论点，其次考虑削弱论据。\n第二步：逐一分析选项。\nA项：该项指出氨基酸在岩浆的高温条件下无法存活，说明高温岩浆的普遍覆盖可能将氨基酸全部消灭，补充论据，可以加强，无法削弱，排除；\nB项：该项指出此前检测出氨基酸的“陨石”是从某深海打捞上来的，但论据研究的是来自小行星的“砂土”，二者并不是同一物质，无法削弱，排除；\nC项：该项指出地球表面并未被岩浆完全覆盖，说明高温岩浆没有普遍覆盖从而将氨基酸全部消灭，地球仍具备生命起源的条件，否定论据，可以削弱，当选；\nD项：该项指出其它小行星和月球表面未发现氨基酸存在的痕迹，而论点讨论的是地球生命起源于外太空，话题不一致，无法削弱，排除。\n故正确答案为C。",
   "exam": "jilin",
   "year": 2023
