   "source": "2024年吉林省公务员录用考试《行测》题 · 第10题",
   "question": "工资歧视是指雇主针对既定的生产率特征支付的价格因劳动者所属的人口群体不同而呈现系统性的差别。 \n根据上述定义，下列符合工资歧视的是：",
   "options": [
    "A. 雇主支付给技术熟练员工的工资高于市场平均水平",
    "B. 在同等条件下，客户倾向于异性销售员提供服务",
    "C. 雇主支付给女员工的工资低于同工作效率的男员工",
    "D. 雇主故意给女性劳动者安排低工资的工作岗位"
   ],
   "answer": "C",
   "analysis": "第一步：找出定义关键词。\n“雇主”、“针对既定的生产率特征”、“支付的价格因劳动者所属的人口群体不同而呈现差别”。\n第二步：逐一分析选项。\nA项：雇主支付给技术熟练员工的工资高于市场平均水平，说明雇主支付给他们更高的工资是因为他们有更高的生产率，并非因为他们所属的人口群体不同，不符合“支付的价格因劳动者所属的人口群体不同而呈现差别”，不符合定义，排除；\nB项：在同等条件下，客户倾向于异性销售员提供服务，只体现了客户对于销售员的性别倾向，未涉及雇主，不符合“雇主”，不符合定义，排除；\nC项：雇主支付给女员工的工资低于同工作效率的男员工，说明在工作效率相同的情况下，男员工和女员工的工资因所属群体不同而有差别，符合“雇主”、“针对既定的生产率特征”、“支付的价格因劳动者所属的人口群体不同而呈现差别”，符合定义，当选；\nD项：雇主故意给女性劳动者安排低工资的工作岗位，只体现了因性别不同，雇主会安排不同工资水平的工作岗位，并未提及不同人口群体的生产率情况，不符合“针对既定的生产率特征”，不符合定义，排除。\n故正确答案为C。",
