   "question": "L国留学人数下降，以某地大学为例，从2019—2022年，两所大学出国留学比例从15.3%和14.8%下降到7.1%和8.4%，下降幅度高至4—5成。有分析人士认为，这是由留学目的国的国内物价上涨造成的。\n以下哪个选项最能支持上述结论？",
